import { benchmarkHistory } from './activity-analysis.js';
import { visualTime } from './activity-visuals.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=d=>new Date(d+'T12:00Z').toLocaleDateString('en-AU',{day:'numeric',month:'short',timeZone:'UTC'});
export const effortDistance=d=>d===804.672?'½ mile':d===1609.344?'1 mile':d===3218.688?'2 miles':d<1000?d+' m':new Intl.NumberFormat('en-AU',{maximumFractionDigits:1}).format(d/1000)+' km';
export function mountBestHistory(root,effort){
 const rows=benchmarkHistory(effort.results),pref=new URLSearchParams(location.search);let selected=pref.get('effort')||rows.at(-1)?.id,mode=pref.get('effortView')==='top10'?'top10':'history';
 function render(){
  if(!rows.length){root.innerHTML='<div class="bh-empty"><h3>Your next distance is waiting.</h3><p>A GPS recording covering this distance will start your history.</p></div>';return;}
  const width=innerWidth<=600?Math.max(300,innerWidth-32):630,right=width-30;
  const row=rows.find(r=>r.id===selected)||rows.at(-1);selected=row.id;
  const sorted=[...rows].sort((a,b)=>a.elapsedS-b.elapsedS||a.date.localeCompare(b.date)||a.id.localeCompare(b.id)),best=sorted[0],index=rows.indexOf(row),min=Math.floor((Math.min(...rows.map(r=>r.elapsedS))-10)/30)*30,max=Math.ceil((Math.max(...rows.map(r=>r.elapsedS))+10)/30)*30;
  const days=[...new Set(rows.map(r=>r.date))].map(day=>rows.filter(r=>r.date===day).reduce((a,b)=>a.elapsedS<b.elapsedS?a:b));
  const first=Date.parse(rows[0].date),span=Math.max(86400000,Date.parse(rows.at(-1).date)-first),x=r=>days.length===1?width/2:58+(Date.parse(r.date)-first)/span*(right-58),y=r=>28+(r.elapsedS-min)/(max-min)*167;
  let line='';for(let i=0;i<days.length;i++){const r=days[i];if(!i)line=`M${x(r)},${y(r)}`;else{const p=days[i-1],mid=(x(p)+x(r))/2;line+=` C${mid},${y(p)} ${mid},${y(r)} ${x(r)},${y(r)}`;}}
  const params=new URLSearchParams(location.search);params.set('effort',selected);params.set('effortView',mode);history.replaceState(null,'',location.pathname+'?'+params);
  root.innerHTML=`<div class="bh-top"><div><span>Best ${effortDistance(effort.distanceM)}</span><strong>${visualTime(best.elapsedS)}<small>${visualTime(best.paceSPerKm)} /km</small></strong><p>${date(best.date)} · ${rows.length} ${rows.length===1?'recording':'recordings'}</p></div><div class="bh-view" role="group" aria-label="Best effort view"><button data-effort-view="history" aria-pressed="${mode==='history'}">Analysis</button><button data-effort-view="top10" aria-pressed="${mode==='top10'}">Top 10</button></div></div>${mode==='history'?`<div class="bh-plot"><svg viewBox="0 0 ${width} 240" role="img" aria-label="${esc(effortDistance(effort.distanceM))} elapsed-time history. Faster times are higher. Use the result selector below for exact values."><defs><linearGradient id="bh-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--color-heartRate)" stop-opacity=".22"/><stop offset="1" stop-color="var(--color-heartRate)" stop-opacity="0"/></linearGradient></defs>${[min,(min+max)/2,max].map(v=>`<path class="bh-grid" d="M58 ${28+(v-min)/(max-min)*167}H${right}"/><text x="0" y="${32+(v-min)/(max-min)*167}">${visualTime(v)}</text>`).join('')}<path class="bh-fill" d="${line} L${x(rows.at(-1))},208H${x(rows[0])}Z"/><path class="bh-line" d="${line}"/>${rows.map(r=>`<circle cx="${x(r)}" cy="${y(r)}" r="${r.id===row.id?7:4}" class="${r.id===row.id?'bh-selected':''}"><title>${date(r.date)} · ${visualTime(r.elapsedS)}</title></circle>`).join('')}<path class="bh-cursor" d="M${x(row)} 20V208"/><text x="58" y="234">${date(rows[0].date)}</text>${days.length>1?`<text x="${right}" y="234" text-anchor="end">${date(rows.at(-1).date)}</text>`:''}</svg></div><div class="bh-inspect"><button type="button" data-effort-step="-1" aria-label="Previous effort" ${index===0?'disabled':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 12H5m6-6-6 6 6 6"/></svg></button><label><span class="sr-only">Inspect a best effort</span><select id="effort-result">${rows.map(r=>`<option value="${esc(r.id)}" ${r.id===row.id?'selected':''}>${date(r.date)} · ${visualTime(r.elapsedS)}</option>`).join('')}</select></label><button type="button" data-effort-step="1" aria-label="Next effort" ${index===rows.length-1?'disabled':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></button></div><div class="bh-chosen"><div><strong>${visualTime(row.elapsedS)}<small>${visualTime(row.paceSPerKm)} /km</small></strong><p>${esc(row.title)}</p>${row.improvementS!==null?`<span class="bh-improvement">${row.improvementS<1?'Under a second':visualTime(row.improvementS)} quicker than your previous best</span>`:row.id===best.id?'<span class="bh-improvement">Best recorded</span>':''}</div><a href="/app.html?activity=${encodeURIComponent(row.id)}">View run <svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a></div>`:`<ol class="bh-ranking">${sorted.slice(0,10).map((r,i)=>`<li><a href="/app.html?activity=${encodeURIComponent(r.id)}"><span>${i+1}</span><div><strong>${visualTime(r.elapsedS)} <small>${visualTime(r.paceSPerKm)} /km</small></strong><p>${esc(r.title)} · ${date(r.date)}</p></div>${i===0?'<em>Best</em>':''}</a></li>`).join('')}</ol>`}<details class="pr-values"><summary>How to read this</summary><p>One fastest elapsed-time effort per run at this distance, from your available GPS recordings since July 2026. Faster is higher. Dots are individual results; the connecting line guides between each day’s best. Improvements compare with earlier calendar dates, so same-day ordering is not guessed.</p></details>`;
  root.querySelectorAll('[data-effort-view]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.effortView;render();root.querySelector(`[data-effort-view="${mode}"]`).focus({preventScroll:true});}));
  root.querySelectorAll('[data-effort-step]').forEach(b=>b.addEventListener('click',()=>{selected=rows[index+Number(b.dataset.effortStep)].id;const direction=b.dataset.effortStep;render();const button=root.querySelector(`[data-effort-step="${direction}"]`);(button.disabled?root.querySelector('#effort-result'):button).focus({preventScroll:true});}));
  root.querySelector('#effort-result')?.addEventListener('change',e=>{selected=e.target.value;render();root.querySelector('#effort-result').focus({preventScroll:true});});
 }
 render();
}
